/**
 * @param {string} s
 * @param {string} t
 * @return {string}
 */
var minWindow = function (s, t) {
    if (!s || !t || s.length < t.length) return "";

    const need = {};
    for (const char of t) {
        need[char] = (need[char] || 0) + 1;
    }

    const required = Object.keys(need).length;
    const window = {};

    let left = 0, right = 1, have = 0, minLen = Infinity, minStart = 0;

    for (let right = 0; right < s.length; right++) {
        const char = s[right];
        window[char] = (window[char] || 0) + 1;

        if (need[char] && window[char] === need[char]) {
            have++;
        }

        // Window is valid, attempt to shrink from the left
        while (have === required) {
            const currentLen = right - left + 1;
            if (currentLen < minLen) {
                minLen = currentLen;
                minStart = left;
            }

            const leftChar = s[left];
            window[leftChar]--;
            if (need[leftChar] && window[leftChar] < need[leftChar]) {
                have--;
            }
            left++;
        }
    }

    return minLen === Infinity ? "" : s.slice(minStart, minStart + minLen);
};


console.log("\n========minWindow()========")
console.log(minWindow());
console.log("\n========minWindow('a', 'a')========")
console.log(minWindow("a", "a"));
